package com.southstand.football.matchdata;
import static org.assertj.core.api.Assertions.assertThat;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;
@SpringBootTest class T17DemoDataCapacityTests{@Autowired JdbcTemplate jdbc;@Test void capacityMeetsAcceptance(){Integer matches=jdbc.queryForObject("SELECT COUNT(DISTINCT match_id) FROM football_match_lineup WHERE source='DEMO' AND is_deleted=0",Integer.class);Integer ratings=jdbc.queryForObject("SELECT COUNT(*) FROM football_user_player_rating WHERE id>=32000000000000001 AND id<33000000000000001 AND status='ACTIVE' AND is_deleted=0",Integer.class);Integer users=jdbc.queryForObject("SELECT COUNT(DISTINCT user_id) FROM football_user_player_rating WHERE id>=32000000000000001 AND id<33000000000000001 AND status='ACTIVE' AND is_deleted=0",Integer.class);assertThat(matches).isEqualTo(20);assertThat(ratings).isGreaterThanOrEqualTo(300);assertThat(users).isGreaterThanOrEqualTo(15);}}
